INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('71daeaed-c564-496d-b033-a01030d22665', 'dfd4d77e-a5ea-48d2-a4c5-2cbcac014636', 0, 'AWS CloudTrail — records a detailed, chronological log of API calls made across an AWS account (by users, roles, and AWS services), capturing WHO made a call (the calling identity), WHAT action was taken, WHEN it occurred, and the source IP it came from, making it the standard tool for exactly this kind of account-activity audit and forensic "who did this" investigation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('989fe5b9-3404-4c19-85ce-b977f7f2e67b', 'dfd4d77e-a5ea-48d2-a4c5-2cbcac014636', 1, 'VPC Flow Logs, since Flow Logs record which specific IAM principal made a given API call and at what time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a82eaa6c-f098-4c1a-8a35-b414cd9b716c', 'dfd4d77e-a5ea-48d2-a4c5-2cbcac014636', 2, 'AWS Config, since Config''s core function is recording which IAM principal made a specific API call and from what source IP.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1947322d-2555-4e63-9e13-331005899438', 'dfd4d77e-a5ea-48d2-a4c5-2cbcac014636', 3, 'AWS provides no service capable of recording which specific IAM principal performed a given API action.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2a71802-1ba6-46be-9baa-e1b61a41bdad', '175bdd3d-d6f7-4870-82db-11ffb567fa03', 0, 'The security group is STATEFUL — once inbound traffic is allowed in, the security group automatically permits the corresponding RETURN traffic out, regardless of outbound rules, because it tracks the connection''s state. The NACL is STATELESS — it evaluates each direction of traffic independently against its own explicit rules, so an inbound-only rule with no matching outbound rule for the ephemeral return ports will actually BLOCK that return traffic, a genuinely common source of "why can''t my client reach this" troubleshooting confusion.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58c745db-2c42-40ee-af74-db64960aaf6e', '175bdd3d-d6f7-4870-82db-11ffb567fa03', 1, 'The NACL is stateful and will automatically allow the return traffic, while the security group is stateless and requires an explicit matching outbound rule.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99084370-ccd3-4010-8d36-200c2a6cdd02', '175bdd3d-d6f7-4870-82db-11ffb567fa03', 2, 'Both the security group and the NACL are fully stateful, so both will automatically allow the return traffic with no explicit outbound rule needed in either case.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b14a50e6-c497-4469-aea8-ece2ae437e82', '175bdd3d-d6f7-4870-82db-11ffb567fa03', 3, 'Neither construct will allow the return traffic under any circumstance without an explicit outbound rule configured on both.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01144e51-ed3a-4246-9909-e669ef6a5523', '49ed2656-c985-4992-ba51-27d09ed9a57c', 0, 'A bucket policy with an explicit Deny statement using the `aws:SecureTransport` condition key set to `false` — this denies any S3 request that did NOT arrive over HTTPS, enforcing encryption-in-transit at the bucket level itself rather than depending on every individual client being correctly configured to use HTTPS on its own, closing the gap left by a purely client-side assumption.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b619649-342b-4da8-98dc-90c3fd2b7cb8', '49ed2656-c985-4992-ba51-27d09ed9a57c', 1, 'Enabling SSE-KMS encryption at rest on the bucket, since encryption at rest automatically also enforces that all requests to the bucket arrive over HTTPS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d46c4e3e-b34d-49f4-a490-0508041e1e90', '49ed2656-c985-4992-ba51-27d09ed9a57c', 2, 'S3 Object Lock, since Object Lock''s core function is rejecting any S3 request made over plain, unencrypted HTTP.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae98dafe-10eb-44a2-b41e-a7bb970fe65b', '49ed2656-c985-4992-ba51-27d09ed9a57c', 3, 'S3 has no mechanism to enforce that requests to a bucket use HTTPS; this depends entirely and unavoidably on individual client configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ff676a6-5832-4083-b80c-add6f1490a12', '7b07d85e-1b7e-4871-8b5a-887871500229', 0, 'IAM Access Analyzer — continuously analyzes resource policies (S3 bucket policies, IAM role trust policies, KMS key policies, and others) across an account or an entire AWS Organization, and specifically surfaces findings where a resource is accessible from OUTSIDE the account/organization''s trusted zone of accounts — directly catching unintentional external exposure that accumulated gradually across many individually-reasonable-looking policy changes, which is exactly the kind of gap that''s hard to spot by manually reviewing policies one at a time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a54803d2-dcc4-4620-91b1-8cd5215fdba3', '7b07d85e-1b7e-4871-8b5a-887871500229', 1, 'AWS Trusted Advisor, since Trusted Advisor''s core function is analyzing every resource and IAM role policy for unintended external access across an organization.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d731c66c-ac36-41ef-bcf9-73530bf15f68', '7b07d85e-1b7e-4871-8b5a-887871500229', 2, 'GuardDuty, since GuardDuty specifically analyzes resource-based and IAM trust policies to identify unintended external access, rather than detecting active threats.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1050a5d6-5867-4155-9b1b-28dc7cdf5c97', '7b07d85e-1b7e-4871-8b5a-887871500229', 3, 'No AWS service can automatically identify unintentional external access across an account''s accumulated resource and IAM policies; this must always be done through manual review alone.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('699551dd-894e-408c-9797-0feea3a37e6f', 'ec4c0f0f-9e18-406a-9daf-68a044d9b99a', 0, 'AWS Network Firewall — a managed, stateful network firewall deployed at the VPC level, supporting domain-name filtering, IP reputation lists, deep packet inspection, and custom rule groups (including intrusion prevention-style signature rules), providing more comprehensive traffic filtering — for traffic entering, leaving, or moving between subnets within a VPC — than security groups (instance-level, covered in Paper 1) or NACLs (subnet-level, covered in Paper 1) alone are designed to provide.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f504e332-49df-472a-a680-b9b6a4f47599', 'ec4c0f0f-9e18-406a-9daf-68a044d9b99a', 1, 'AWS WAF, since WAF is specifically designed to inspect and filter traffic at the VPC level based on domain names and IP reputation, rather than at the web-application-request layer.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37506ab2-c9c2-4381-8202-cf9319399b82', 'ec4c0f0f-9e18-406a-9daf-68a044d9b99a', 2, 'A Gateway VPC Endpoint, since Gateway Endpoints provide stateful, VPC-wide traffic inspection based on domain names and IP reputation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb5c7523-ac85-41cd-8b18-03973dd53b40', 'ec4c0f0f-9e18-406a-9daf-68a044d9b99a', 3, 'No managed AWS service exists for VPC-level stateful traffic inspection; only security groups and NACLs are available for any traffic filtering need.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f57e669b-e057-45bf-84e9-3c214a3e630f', 'b0e02984-89e5-481b-896e-808b295aa936', 0, 'VPC Peering connections are NOT transitive — a peering connection only allows direct communication between the two SPECIFIC VPCs it directly connects, so VPC A being peered with B, and B being peered with C, does NOT automatically allow A to reach C; a direct A-to-C peering connection would need to be created separately. Transit Gateway (covered generally in Paper 5) solves this specific limitation by acting as a central hub all VPCs connect to once, enabling transitive routing between every attached VPC without needing a separate point-to-point connection for every single pair.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c83cd27-24a8-4fa0-95ff-10edb059fb89', 'b0e02984-89e5-481b-896e-808b295aa936', 1, 'VPC Peering connections are fully transitive by default, so this scenario describes a misconfiguration rather than an inherent limitation of VPC Peering itself.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72e7e6bb-8f34-477e-bd22-7eddf89532d7', 'b0e02984-89e5-481b-896e-808b295aa936', 2, 'Transit Gateway has the exact same non-transitive limitation as VPC Peering, with no meaningful difference in how the two handle multi-VPC connectivity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('998cee05-8eec-412f-9067-cd1c2e1bfb2e', 'b0e02984-89e5-481b-896e-808b295aa936', 3, 'VPC Peering connections can never connect more than two VPCs under any circumstance, even with multiple separate peering connections configured.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8888e96b-9ba4-4e64-83dc-fc9a58c541f4', '75732e68-3023-4215-957a-b8997f954672', 0, 'Same-Region Replication (SRR) — automatically and asynchronously replicates objects to a DIFFERENT bucket within the SAME AWS Region, suited to needs like regulatory data-residency requirements that specifically prohibit moving data to another region, maintaining a separate compliance/audit copy, or aggregating data from multiple buckets — genuinely distinct from Cross-Region Replication (CRR, covered generally in Papers 1 and 5), which specifically moves data to a DIFFERENT region, typically for disaster recovery or global latency purposes.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2dd4df0-3df8-4e30-b905-f6e6ae36f4d5', '75732e68-3023-4215-957a-b8997f954672', 1, 'Cross-Region Replication is the only S3 replication feature that exists; there is no way to replicate objects to a second bucket within the same Region.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23b372f0-68fc-449f-a903-490c12726557', '75732e68-3023-4215-957a-b8997f954672', 2, 'S3 Object Lock, since Object Lock''s core function is replicating objects to a second bucket within the same AWS Region.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e2efbba-ca81-4be0-bc7b-dcac92bfc170', '75732e68-3023-4215-957a-b8997f954672', 3, 'S3 Transfer Acceleration, since Transfer Acceleration is the feature that replicates objects to a separate bucket within the same Region.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e41d8a4-28cf-4ef9-a857-b13532383917', '882745fe-cbd7-4697-b057-530c2226f6ce', 0, 'DynamoDB Point-in-Time Recovery (PITR) — once enabled, continuously backs up a table''s data automatically (with no manual backup scheduling required), enabling restoration to any specific second within a configurable retention window of up to 35 days, protecting against exactly this kind of accidental deletion or corruption without an administrator needing to manage individual backup jobs at all.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f98eeea-f010-4fdb-866c-ffc6fcd7c4cf', '882745fe-cbd7-4697-b057-530c2226f6ce', 1, 'DynamoDB Global Tables, since Global Tables'' core function is continuously backing up a table for restoration to any specific second within the last 35 days.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('021d066d-6c2a-46e1-a9d7-72799604d256', '882745fe-cbd7-4697-b057-530c2226f6ce', 2, 'DynamoDB Accelerator (DAX), since DAX provides continuous point-in-time backup and restoration for a DynamoDB table.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e949d88e-def5-4541-a502-37792816d4e1', '882745fe-cbd7-4697-b057-530c2226f6ce', 3, 'DynamoDB provides no mechanism for restoring a table to a specific point in time; only full, manually-scheduled table backups are possible.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a389030-719c-481b-9fb1-025e8a58541c', '867c0349-5df5-4c8f-b15b-2a893e163b64', 0, 'Aurora Backtrack — rewinds an Aurora cluster to a specific point in time IN PLACE, without creating an entirely new database instance and without the time cost of a full point-in-time restore-and-swap process, making it well suited to quickly undoing the effects of a recent, specific mistake (like an erroneous bulk update) when the target recovery point is close to the current time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6efb6e9-13ba-4de1-aeaa-33b584f7161e', '867c0349-5df5-4c8f-b15b-2a893e163b64', 1, 'Aurora Global Database, since Aurora Global Database''s core function is rewinding a cluster in place to undo a recent erroneous bulk update.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3d15614-cecd-460b-b6d1-0027589c7dc0', '867c0349-5df5-4c8f-b15b-2a893e163b64', 2, 'Aurora Serverless v2, since Aurora Serverless v2 is specifically designed to rewind a database cluster to a point in time without creating a new instance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('acf7b579-3776-417c-b269-ad2b8f46dba2', '867c0349-5df5-4c8f-b15b-2a893e163b64', 3, 'Aurora has no feature for quickly undoing a recent erroneous change; a full point-in-time restore to a new instance is always the only available option.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('394ca793-845c-4424-a911-042ddd1a328f', '471bef5d-7e7b-4ce7-8a3f-03042c2717f1', 0, 'MFA Delete — an additional S3 Versioning setting that specifically requires the bucket owner''s MFA authentication to (1) permanently delete a specific object version, or (2) change the bucket''s versioning state (like suspending it) — adding a genuinely meaningful extra barrier against exactly the "compromised single credential" scenario, since a stolen access key alone is no longer sufficient to perform either of these particularly destructive actions without also having the physical/registered MFA device.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d626c1d-bef6-464a-82ef-9b91c33e4624', '471bef5d-7e7b-4ce7-8a3f-03042c2717f1', 1, 'S3 Object Lock, since Object Lock is the setting that specifically requires MFA authentication to permanently delete a version or change versioning state.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d603932c-2743-438d-9d56-b5feb1f4ccb2', '471bef5d-7e7b-4ce7-8a3f-03042c2717f1', 2, 'S3 Same-Region Replication, since SRR requires MFA authentication before permanently deleting an object version or altering versioning state.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c677db75-5c7d-48d2-8917-07d076c70a9e', '471bef5d-7e7b-4ce7-8a3f-03042c2717f1', 3, 'S3 Versioning alone, with no additional setting, already fully prevents any possibility of permanent version deletion under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9476e5e4-89ac-456f-bfd8-9838c844fc9e', 'f4dbb689-dcb7-4199-a598-f2c0bd0f1de0', 0, 'Yes — EFS is inherently a REGIONAL, Multi-AZ service by design, automatically storing data redundantly across multiple Availability Zones within a Region with no additional Multi-AZ configuration required, so it remains available even if one entire AZ becomes unreachable; this is a fundamental architectural difference from a standard EBS volume (covered generally in Paper 1), which is inherently tied to a SINGLE specific Availability Zone and is not directly accessible from instances in a different AZ without a separate replication or snapshot-based mechanism.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53f8a481-3193-4e3b-b1c5-d138372fd106', 'f4dbb689-dcb7-4199-a598-f2c0bd0f1de0', 1, 'No — EFS is inherently tied to a single Availability Zone by default, identically to a standard EBS volume, and requires explicit additional Multi-AZ configuration to survive an AZ outage.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c634b9b7-d9a0-468d-b7be-f6bee12dca09', 'f4dbb689-dcb7-4199-a598-f2c0bd0f1de0', 2, 'EFS and EBS provide identical Multi-AZ availability characteristics by default, with no architectural difference between the two services in this respect.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d578bfc-f84b-4514-805e-291a65a894eb', 'f4dbb689-dcb7-4199-a598-f2c0bd0f1de0', 3, 'Neither EFS nor EBS can be made available across multiple Availability Zones under any circumstance, with or without additional configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('810b1f41-0e75-4381-b5d7-536d4a875c1a', '42b365e5-bccd-432d-9d2c-f1925d8a187f', 0, 'ElastiCache for Redis supports data persistence (snapshotting to disk), built-in replication with automatic failover for high availability, and complex data structures (sorted sets, lists, hashes, not just simple key-value pairs) — directly fitting this requirement; Memcached, by contrast, offers no persistence or built-in replication, but its main advantage is simplicity and native multi-threaded architecture, which can provide higher raw throughput for simple, high-volume key-value caching workloads that don''t need Redis''s richer feature set.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3004ba31-a5c2-448e-a010-4ffe060f1941', '42b365e5-bccd-432d-9d2c-f1925d8a187f', 1, 'ElastiCache for Memcached is the engine that supports data persistence, built-in replication, and complex data structures, while Redis offers only simple key-value caching with no advanced features.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42e23b76-baba-4319-b540-bc927f52c52b', '42b365e5-bccd-432d-9d2c-f1925d8a187f', 2, 'Redis and Memcached are functionally identical engines with no meaningful difference in persistence, replication, or data structure support.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c7fb706-c662-4442-82a5-b5c1d8209f4a', '42b365e5-bccd-432d-9d2c-f1925d8a187f', 3, 'ElastiCache does not support any form of data persistence or replication under either engine; all cached data is always fully ephemeral with no exception.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc8bfd38-6247-4dce-9786-bf68e59a67b6', '3df4885a-e92a-497b-b96f-f7709b154266', 0, 'Enhanced Networking — uses techniques like single root I/O virtualization (SR-IOV) to provide higher packets-per-second (PPS) performance, lower inter-instance latency, and lower jitter compared to traditional virtualized networking, by giving the instance more direct access to the underlying network hardware; most current-generation instance types support it by default or with a straightforward driver-level enablement, with no instance type CHANGE required.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb76d5da-82e0-4ee6-be91-ea3cec19cd68', '3df4885a-e92a-497b-b96f-f7709b154266', 1, 'EBS optimization, since EBS-optimized instances are the feature that specifically reduces network latency, jitter, and increases packets-per-second capacity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac3f4cf7-e44f-4ca6-a701-39d678d2faba', '3df4885a-e92a-497b-b96f-f7709b154266', 2, 'Placement Groups, since Placement Groups are defined as the feature providing SR-IOV-based higher packets-per-second and lower jitter on a single instance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7053cae1-4e6a-440d-a67c-c2e4d09fa3f5', '3df4885a-e92a-497b-b96f-f7709b154266', 3, 'EC2 network performance is entirely fixed by instance type alone, with no feature able to improve packets-per-second, latency, or jitter beyond that baseline.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1996282-d668-446d-8aa5-59010fecb8b5', '4c87b3f8-c788-43fc-862c-c49f3f489cdb', 0, 'S3 byte-range GET requests — an S3 GET request can specify a `Range` header requesting only a specific byte range of an object, rather than the object''s complete contents, allowing an application (or CloudFront in front of it) to fetch only the specific portion of a large file actually needed for a given moment (like a video seek), and enabling parallel downloading of different ranges simultaneously to improve overall throughput for very large objects.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d234e0b9-31b8-4620-a5fb-badbd1094dcd', '4c87b3f8-c788-43fc-862c-c49f3f489cdb', 1, 'S3 Multipart Upload, since Multipart Upload is the mechanism for retrieving only a specific byte range of an object during a GET request.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d27e0c76-4a5f-445c-b49f-ad8690d39a7c', '4c87b3f8-c788-43fc-862c-c49f3f489cdb', 2, 'S3 Select, since S3 Select''s core function is retrieving arbitrary byte ranges of unstructured video file content.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('110cb30f-d460-49aa-9e50-4366e757e1e7', '4c87b3f8-c788-43fc-862c-c49f3f489cdb', 3, 'S3 GET requests can only ever retrieve an object''s complete contents in full; there is no mechanism for requesting a partial byte range.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('472257ec-1353-4e95-8223-382bd489d939', '315c73ff-3728-4809-a479-5053c3a0b228', 0, 'Lambda@Edge — runs Lambda functions directly at CloudFront''s globally distributed edge locations, close to the end user, allowing custom logic (URL rewrites, header inspection/modification, generating a response without ever reaching the origin) to execute as part of the CloudFront request/response lifecycle, reducing latency compared to routing that same logic all the way back to an origin server for every request.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75021d9b-aa66-44cd-a76c-60a1ffe3346c', '315c73ff-3728-4809-a479-5053c3a0b228', 1, 'AWS Step Functions, since Step Functions'' core function is running custom logic directly at CloudFront''s globally distributed edge locations.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d8be0b5-78e9-45f1-bab0-7d56e378a4f0', '315c73ff-3728-4809-a479-5053c3a0b228', 2, 'Provisioned concurrency, since provisioned concurrency is the mechanism that executes custom logic at CloudFront edge locations rather than in a specific AWS Region.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5dbfb549-3677-40f9-b36d-fe4917e5e770', '315c73ff-3728-4809-a479-5053c3a0b228', 3, 'CloudFront has no capability to run custom code at the edge; all request/response logic must always execute at the origin server.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1fac2c18-6f98-4bcd-a7d2-83a10be26a23', '5d5d44c1-9b15-4e34-9783-83aa442eff6b', 0, 'S3 Multi-Region Access Points — provides a single, global endpoint that automatically routes requests to the lowest-latency replicated copy of the underlying data across multiple Regions (working together with S3 Cross-Region Replication to keep those copies in sync), so an application uses ONE endpoint without needing its own custom logic to determine which regional bucket to query for the best latency.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35fbd1ce-b197-4ed3-8819-3debec3b6181', '5d5d44c1-9b15-4e34-9783-83aa442eff6b', 1, 'S3 Object Lock, since Object Lock''s core function is providing a single global endpoint that automatically routes requests to the lowest-latency regional copy of data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b91b925-a468-4c9e-ac4a-ab8c8c46991f', '5d5d44c1-9b15-4e34-9783-83aa442eff6b', 2, 'S3 Requester Pays, since Requester Pays is the feature that automatically routes multi-region requests to the lowest-latency replicated copy.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1259b54d-d385-4511-984c-87f8c3440b2d', '5d5d44c1-9b15-4e34-9783-83aa442eff6b', 3, 'S3 provides no mechanism for simplifying multi-region access to replicated data; applications must always hardcode their own region-selection logic across separate bucket endpoints.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12684af8-33e5-4b61-91c7-9a914f29750c', 'ec396760-29d1-404c-9b10-fbbd2b84d6f8', 0, 'S3 Glacier Deep Archive — the lowest-cost S3 storage class available, purpose-built for data retained for extended, multi-year periods (like this 10-year compliance retention requirement) with genuinely rare access; its trade-off compared to S3 Glacier (Flexible Retrieval) is retrieval TIME — Deep Archive retrieval standard tier typically takes around 12 hours, meaningfully longer than Glacier Flexible Retrieval''s standard retrieval (typically a few hours), a direct cost-versus-retrieval-speed trade-off appropriate specifically because this data is accessed so rarely that the extra retrieval wait time genuinely doesn''t matter in exchange for the lowest possible ongoing storage cost.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc9ac82a-10a1-48ed-99e6-4e6bf4ef9871', 'ec396760-29d1-404c-9b10-fbbd2b84d6f8', 1, 'S3 Standard, since S3 Standard is specifically the lowest-cost storage class for data retained for 10 years with genuinely rare access.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34f41bc3-f5d6-4b68-9557-bee9b83408c7', 'ec396760-29d1-404c-9b10-fbbd2b84d6f8', 2, 'S3 Intelligent-Tiering, since Intelligent-Tiering always provides a lower cost than every other S3 storage class for any access pattern, including 10-year archival retention.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5782b86-e79a-4fd6-a471-40f7a6feb5b2', 'ec396760-29d1-404c-9b10-fbbd2b84d6f8', 3, 'S3 offers no storage class specifically optimized for long-term, rarely-accessed archival data; every storage class has identical cost regardless of access frequency or retention period.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d9b04f5-a496-45f5-a904-731ea8c5409e', '6f34cd01-73b4-41fb-8858-581760d03bbc', 0, 'AWS Cost Anomaly Detection — uses machine learning to learn an account''s normal spending PATTERNS over time, and automatically alerts when spending deviates from that learned pattern in a statistically unusual way, catching unexpected cost spikes that might not yet have crossed any manually-configured fixed dollar threshold in AWS Budgets, and without requiring someone to notice the deviation themselves while manually reviewing Cost Explorer.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('104c249e-d85f-4a18-b2dd-cf26f4c3f267', '6f34cd01-73b4-41fb-8858-581760d03bbc', 1, 'AWS Compute Optimizer, since Compute Optimizer''s core function is using machine learning to detect statistically unusual AWS spending patterns and alert on them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2150c22a-6f53-44fa-a2cf-8b6d4acc0ceb', '6f34cd01-73b4-41fb-8858-581760d03bbc', 2, 'AWS Budgets Actions, since Budgets Actions is defined as automatically learning an account''s normal spending pattern using machine learning, independent of any manually-configured threshold.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('898dd6b5-0826-43be-bf03-b0916db4b47d', '6f34cd01-73b4-41fb-8858-581760d03bbc', 3, 'No AWS service exists to automatically detect statistically unusual spending patterns; only fixed, manually-configured dollar thresholds are available for any cost alerting.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6ff262a-5b33-430a-9af6-fa17f321d152', '6f644598-4c9b-4ef3-8682-0779aa44cedc', 0, 'The `capacity-optimized` allocation strategy — launches instances from the Spot capacity pools AWS estimates have the deepest available capacity and therefore the LOWEST likelihood of near-term interruption, potentially at a slightly higher price than the strict cheapest option, directly prioritizing minimizing interruption over squeezing out the absolute lowest possible price — the inverse trade-off of the `lowest-price` allocation strategy, which instead always selects the cheapest available Spot pools regardless of that pool''s relative interruption risk.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c661a6d-4d6b-453a-890d-93929bb42026', '6f644598-4c9b-4ef3-8682-0779aa44cedc', 1, 'The `lowest-price` allocation strategy, since `lowest-price` is defined as prioritizing the deepest available capacity pools with the lowest interruption likelihood over the cheapest price.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8ff8d10-8d4f-4d7c-a52e-695a57691d77', '6f644598-4c9b-4ef3-8682-0779aa44cedc', 2, 'Spot Fleet has no configurable allocation strategy; every Spot Fleet always selects instances using an identical, fixed, non-configurable method.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e922c010-2311-46ac-b4ac-cfa305276aee', '6f644598-4c9b-4ef3-8682-0779aa44cedc', 3, 'Spot capacity availability and interruption likelihood are always identical and uniform across every instance type and Availability Zone, making any allocation strategy choice irrelevant.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f09e00c5-7280-474c-b36f-b0704d168032', 'f68891b7-a680-41ef-97e6-76cbf7782a9d', 0, 'Placing a CloudFront distribution in front of the S3 bucket as its origin — repeated requests for the same popular content get served from CloudFront''s cached copy at edge locations WITHOUT reaching back to the S3 origin at all for each request, meaningfully reducing the volume of data transferred directly OUT of S3 itself (since CloudFront-to-viewer data transfer is typically priced differently, and often more favorably at higher volumes, than direct S3-to-internet data transfer, and cache hits avoid hitting the origin at all).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13a60447-7874-4f14-aebf-7af366bf2f76', 'f68891b7-a680-41ef-97e6-76cbf7782a9d', 1, 'Enabling S3 Requester Pays, since Requester Pays reduces the bucket owner''s own S3 data transfer OUT costs for a popular, publicly-served static asset bucket.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae0d5d28-dda1-48a6-a179-ab20434d10ef', 'f68891b7-a680-41ef-97e6-76cbf7782a9d', 2, 'Enabling S3 Versioning, since S3 Versioning is the standard mechanism for reducing data transfer OUT costs for frequently-requested static content.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a43a5ffd-2a2b-4962-8431-d338a2169ca8', 'f68891b7-a680-41ef-97e6-76cbf7782a9d', 3, 'S3 data transfer OUT costs for popular, frequently-requested static content cannot be reduced by any architectural change; the cost is always fixed regardless of caching or content delivery configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
